      "explanation": "The resting membrane potential (RMP) of a neuron, typically around -70 mV, is primarily established by the differential permeability of the cell membrane to various ions and the concentration gradients of these ions. At rest, the neuronal membrane is significantly more permeable to potassium ions (K⁺) than to other ions like sodium (Na⁺) or chloride . This high permeability is due to the presence of numerous open leak potassium channels. Because the concentration of K⁺ is much higher inside the cell than outside, K⁺ ions tend to diffuse out of the cell down their concentration gradient. As these positively charged ions leave the cell, they make the inside of the membrane negative relative to the outside. This outflow continues until the electrical gradient pulling K⁺ back into the cell balances the concentration gradient pushing it out, establishing the equilibrium potential for potassium, which is very close to the RMP.",
