      "correct": "A",
      "answerText": "(A) TMP",
      "explanation": "Methotrexate is a folate antagonist that competitively inhibits the enzyme dihydrofolate reductase (DHFR). DHFR is essential for reducing dihydrofolate to tetrahydrofolate (THF). THF is a crucial coenzyme that acts as a one-carbon donor in various metabolic pathways, including the synthesis of purines (leading to AMP and GMP) and, most critically, the synthesis of pyrimidines. Specifically, a derivative of THF, N5,N10-methylene-THF, is required for the conversion of deoxyuridine monophosphate (dUMP) to deoxythymidine monophosphate (dTMP), a reaction catalyzed by thymidylate synthase. By depleting the pool of THF, methotrexate indirectly but potently inhibits thymidylate synthase, thereby blocking the synthesis of TMP. Since thymine is a unique component of DNA, this inhibition halts DNA replication and cell division, which is the basis for methotrexate's use as a chemotherapeutic and immunosuppressive agent.",
