      "correct": "A",
      "answerText": "(A) Chemotaxis",
      "explanation": "Interleukin-8 (IL-8), now also known as CXCL8, is a proinflammatory chemokine. Its primary and most potent biological function is to act as a chemoattractant, primarily for neutrophils. This process is known as chemotaxis. IL-8 is produced by various cells, including macrophages and endothelial cells, in response to inflammatory stimuli. It creates a chemical gradient that directs the migration of neutrophils from the bloodstream to the site of inflammation or infection, where they can perform their phagocytic functions. While the inflammatory cascade is complex, the specific and defining role of IL-8 is this recruitment of neutrophils. Lymphocyte proliferation (Option B) is stimulated by other interleukins like IL-2. TH1 activation (Option C) is driven by IL-12. Fever (Option D) is a systemic effect mediated primarily by IL-1, IL-6, and TNF-α.",
