      "number": 81,
      "statement": "Which type of PCR technique is most appropriate for identifying a clinical syndrome that may be caused by multiple different pathogens?",
      "options": [
        "RT-PCR",
        "Multiplex PCR",
        "Nested PCR",
        "Conventional PCR"
      ],
      "correct": "B",
      "answerText": "(B) Multiplex PCR",
      "explanation": "When a clinical syndrome can be caused by several different pathogens (e.g., a respiratory infection panel or a meningitis panel), it is most efficient to test for all potential agents simultaneously. Multiplex PCR is a technique specifically designed for this purpose. It uses multiple sets of primers within a single PCR mixture to amplify DNA or RNA sequences from several different organisms in one reaction. This allows for the simultaneous detection and identification of multiple pathogens, saving time, resources, and patient sample compared to running individual conventional PCRs for each suspected agent. RT-PCR (Option A) is used to amplify RNA targets (by first converting them to cDNA). Nested PCR (Option C) is used to increase the sensitivity and specificity of a reaction but typically targets a single pathogen. Conventional PCR (Option D) also targets a single sequence per reaction.",
