      "explanation": "While historically beta-blockers were contraindicated in heart failure, several specific agents have been proven in large clinical trials to improve survival and reduce hospitalizations in patients with chronic heart failure with reduced ejection fraction (HFrEF). These are known as evidence-based beta-blockers. The three main ones are carvedilol (a non-selective beta-blocker with alpha-1 blocking activity), metoprolol succinate (a long-acting cardioselective beta-1 blocker), and bisoprolol. Bisoprolol is a highly cardioselective beta-1 blocker, and its efficacy in reducing mortality in HFrEF was established in the CIBIS-II trial. Propranolol (Option A) is non-selective and not approved for this indication. Labetalol (Option C) is a non-selective beta-blocker with alpha-blocking properties used for hypertension but not proven for mortality benefit in HFrEF. Pindolol (Option D) has intrinsic sympathomimetic activity and is contraindicated in heart failure.",
