      "correct": "C",
      "answerText": "(C) Propylthiouracil",
      "explanation": "The management of hyperthyroidism during pregnancy requires careful selection of antithyroid medication to minimize risks to the fetus. Propylthiouracil (PTU) is the preferred drug during the first trimester of pregnancy. This is because methimazole (Option A) and its prodrug carbimazole (Option B) have been associated with a small but significant risk of congenital malformations (embryopathy), including aplasia cutis and esophageal atresia, when used during the period of organogenesis. PTU is considered safer in this early stage. After the first trimester, it is common practice to switch the patient from PTU back to methimazole, as PTU carries a higher risk of maternal hepatotoxicity with long-term use. Radioactive iodine (Option D) is absolutely contraindicated during pregnancy as it can cross the placenta and ablate the fetal thyroid gland.",
