      "correct": "C",
      "answerText": "(C) Tenecteplase",
      "explanation": "The diagram illustrates the fibrinolytic (clot-dissolving) pathway. In this process, plasminogen is converted into plasmin by an activator. Plasmin then breaks down fibrin, leading to the formation of fibrin degradation products and dissolution of the blood clot.\nIn the figure, Drug X is shown acting at the step where plasminogen is converted into plasmin, similar to streptokinase. Drugs that act at this step are known as thrombolytic or fibrinolytic agents. They activate plasminogen and promote clot breakdown.\nTenecteplase is a recombinant tissue plasminogen activator (tPA) used clinically for thrombolysis, particularly in conditions such as acute myocardial infarction, pulmonary embolism, and ischemic stroke. It converts plasminogen into plasmin, which then degrades fibrin in the clot.\nThe other options do not directly activate plasminogen. Epsilon-aminocaproic acid is an antifibrinolytic drug that inhibits plasmin. Clopidogrel and aspirin are antiplatelet drugs that prevent platelet aggregation but do not dissolve existing clots.\nTherefore, the drug represented by Drug X in the fibrinolytic pathway is Tenecteplase.",
