      "number": 93,
      "statement": "A person was on long-term antihypertensive therapy and continued the medication despite experiencing side effects such as constipation, dry mouth, and dizziness. He took the drug regularly but forgot to carry it while traveling abroad and subsequently developed a hypertensive emergency. Which antihypertensive drug was he most likely using?",
