      "statement": "A patient with HIV infection who is receiving antiretroviral therapy with zidovudine, lamivudine, and nevirapine is newly diagnosed with tuberculosis. In view of potential drug– drug interactions, which antitubercular drug should be modified or replaced in this patient?",
