      "explanation": "1. In mixed malaria infection with Plasmodium vivax and Plasmodium falciparum, treatment should cover both species. According to malaria treatment guidelines used in many parts of India, including Rajasthan, the recommended therapy is Artemisinin-based Combination Therapy (ACT) along with primaquine.\n2. Artesunate is an artemisinin derivative that rapidly reduces parasitemia by killing the blood stages of the parasite. For a patient weighing 50 kg, the recommended dose is 200 mg, which corresponds to four tablets of 50 mg. Artesunate is given for three days.\n3. Sulfadoxine–pyrimethamine (SP) is administered as a single dose on day 1 or day 2 along with artesunate as part of ACT. It works by inhibiting folate synthesis in the parasite, enhancing the effectiveness of artesunate.\n4. Primaquine is added to eliminate gametocytes of P. falciparum and prevent transmission. A low single dose of primaquine (0.25 mg/kg) is recommended in falciparum or mixed infections.\nTherefore, the appropriate day-2 regimen includes artesunate, sulfadoxine–pyrimethamine, and low-dose primaquine, corresponding to Option (C).",
