      "answerText": "(A) Cocaine intoxication",
      "explanation": "The patient's clinical presentation is a classic sympathomimetic toxidrome. This is characterized by widespread stimulation of the sympathetic nervous system, leading to tachycardia, hypertension, mydriasis (dilated pupils), diaphoresis (sweating), tremors, and agitation. Cocaine is a potent sympathomimetic agent that works by blocking the reuptake of norepinephrine, dopamine, and serotonin, leading to this state of hyperexcitability. Dhatura poisoning (Option B) would cause an anticholinergic toxidrome, characterized by mydriasis, tachycardia, and hypertension, but with dry skin and mucous membranes (mad as a hatter, blind as a bat, red as a beet, hot as a hare, dry as a bone). Cannabis (Option C) typically causes tachycardia and conjunctival injection but not usually severe hypertension or tremors. Alcohol intoxication (Option D) is a CNS depressant. The presence of diaphoresis is a key feature that points towards a sympathomimetic rather than an anticholinergic syndrome.",
