      "number": 116,
      "statement": "What is the typical order in which rigor mortis develops and progresses through the muscles of the human body?",
      "options": [
        "Centre to periphery",
        "Head to foot",
        "Foot to head",
        "Simultaneously"
      ],
      "correct": "B",
      "answerText": "(B) Head to foot",
      "explanation": "Rigor mortis is the postmortem stiffening of muscles due to the depletion of ATP, which prevents the detachment of myosin heads from actin filaments. The onset and progression of rigor mortis follow a predictable pattern, described by Nysten's Law. It typically begins in the smaller muscle groups and progresses to the larger ones. The sequence starts in the muscles of the face and jaw (eyelids, jaw muscles), then spreads downwards to the muscles of the neck, upper limbs, trunk, and finally to the lower limbs. This classic cephalocaudal or head-to-foot progression is due to the different metabolic rates and glycogen stores in various muscle groups. The process usually begins 2-4 hours after death, is fully established in about 12 hours, persists for another 12 hours, and then resolves in the same head-to-foot sequence as decomposition begins.",
