      "explanation": "To protect the privacy, dignity, and safety of victims of sexual assault, and to encourage reporting without fear of public humiliation, the legal systems in many countries, including India, have specific provisions for recording their testimony. According to Section 327(2) of the Code of Criminal Procedure (CrPC) in India, the inquiry into and trial of rape or related sexual offenses shall be conducted in camera. This means the proceedings are not held in an open court accessible to the public and press. The term on camera is often used synonymously with in camera in this context, referring to a private hearing within the judge's chambers or a courtroom cleared of all persons except those directly involved in the case (judge, lawyers, court staff, accused, and the victim with a support person). This ensures confidentiality and creates a less intimidating environment for the victim to give their evidence.",
