      "correct": "C",
      "answerText": "(C) Knee and wrist",
      "explanation": "For medicolegal age estimation in adolescents and young adults, radiographic examination of ossification centers is a standard method. The age of 18 is a crucial legal threshold, and the fusion of various epiphyses occurs around this time. The most commonly used and reliable joints for assessing the 16-18 year age range are the wrist and the knee. In the wrist, the fusion of the distal radial and ulnar epiphyses is a key indicator. At the knee, the fusion of the distal femoral and proximal tibial epiphyses is assessed. The fusion of these centers is generally complete or nearing completion around 18 years of age in males, providing strong evidence to differentiate a 16-year-old from an 18-year-old. The elbow joint (Option D) fuses earlier, typically around 14-16 years, making it less useful for distinguishing 16 from 18. The hip also fuses in the mid-to-late teens.",
