      "correct": "A",
      "answerText": "(A) Desferrioxamine",
      "explanation": "The specific chelating agent used for the treatment of acute iron poisoning is desferrioxamine (also spelled deferoxamine). It is a hexadentate iron chelator, meaning one molecule of desferrioxamine can bind tightly to one atom of ferric iron (Fe³⁺), forming a stable, water-soluble complex called ferrioxamine. This complex is non-toxic and is readily excreted by the kidneys, giving the urine a characteristic reddish-brown or vin rosé color. This process effectively removes excess free iron from the plasma and tissues, preventing it from causing severe cellular damage, metabolic acidosis, and shock. British Anti-Lewisite (BAL, dimercaprol) (Option B) is used for arsenic, mercury, and lead poisoning. Calcium disodium edetate (EDTA) (Option C) is used for lead poisoning. Diethylenetriaminepentaacetic acid (DTPA) (Option D) is used for internal contamination with transuranic radioactive elements.",
