      "correct": "A",
      "answerText": "(A) Alpha-1 antitrypsin",
      "explanation": "Emphysema is characterized by the permanent enlargement of airspaces distal to the terminal bronchioles, accompanied by the destruction of their walls. Panacinar (or panlobular) emphysema, which affects the entire acinus uniformly and is most severe in the lower lobes of the lungs, is the classic form associated with alpha-1 antitrypsin (AAT) deficiency. AAT is a protease inhibitor produced by the liver that circulates in the blood. Its primary function in the lung is to protect the elastic tissue of the alveolar walls from destruction by proteases, particularly neutrophil elastase, which is released by neutrophils during inflammation. In AAT deficiency, this protective shield is absent, leading to unchecked elastase activity and progressive destruction of the lung parenchyma. Centriacinar emphysema, in contrast, is typically associated with smoking. Surfactant (Option B) deficiency causes neonatal respiratory distress syndrome.",
