      "answerText": "(A) Head turned to right, eyeball moves to left with nystagmus",
      "explanation": "The head impulse (head thrust) test is used to assess the vestibulo-ocular reflex (VOR). In a normal VOR, when the head is rapidly rotated, the eyes move in the opposite direction to keep gaze fixed on the target.\nIn right vestibular neuronitis, the right horizontal semicircular canal and nerve are impaired.\nWhen the examiner quickly turns the head to the right (affected side), the vestibular system cannot generate the compensatory eye movement.\nAs a result, the eyes briefly move with the head (to the right) and then make a corrective saccade to the left to refocus on the target.\nThis appears as the eyeball moving to the left with a corrective saccade/nystagmus after a head thrust to the right.\nThus, the abnormal finding is : Head turned to right fv eyeball moves to left with corrective nystagmus.",
