      "answerText": "(C) Submucosal resection (SMR)",
      "explanation": "A septal perforation, as shown in the image, is a known complication of septal surgery. Submucosal resection (SMR) is an older surgical technique for correcting a deviated nasal septum. It involves removing a significant portion of the septal cartilage and bone while attempting to preserve the overlying mucoperichondrial flaps. A major risk of this procedure is the creation of opposing tears in the mucosal flaps on both sides of the septum. If this occurs, or if the blood supply to the flaps is compromised, the cartilage can become avascular and necrotic, leading to the formation of a perforation. This can cause symptoms like crusting, whistling during breathing, and recurrent epistaxis (nosebleeds). FESS (Option A), Caldwell-Luc (Option B), and turbinate surgery (Option D) do not directly involve extensive dissection of the nasal septum and are not the typical causes of septal perforation.",
