      "correct": "C",
      "answerText": "(C) CN IX & X",
      "explanation": "The gag reflex is a brainstem reflex that involves two primary cranial nerves. The afferent (sensory) limb of the reflex arc is mediated by the glossopharyngeal nerve (CN IX), which carries sensory information from the posterior tongue, pharynx, and soft palate. The efferent (motor) limb is primarily carried by the vagus nerve (CN X), which innervates the muscles of the soft palate and pharynx, causing them to contract and elevate during the gag response. A lesion affecting either the sensory input (CN IX) or the motor output (CN X) will result in an impaired or absent gag reflex. Therefore, the combination of CN IX and CN X is correct. The other nerve pairings are not involved in this specific reflex : CN V (sensation to anterior face), CN VI (lateral rectus muscle), CN VII (facial expression), CN VIII (hearing/balance), CN XI (sternocleidomastoid/trapezius).",
