      "answerText": "(A) CECT (Contrast-Enhanced CT)",
      "explanation": "The clinical picture of a male adolescent with recurrent, severe, unilateral epistaxis and a vascular mass in the nasopharynx is classic for a Juvenile Nasopharyngeal Angiofibroma (JNA). This is a benign but locally aggressive and highly vascular tumor. The most important initial step in diagnosis and evaluation is imaging. A Contrast-Enhanced CT (CECT) scan is the investigation of choice. It will show a densely enhancing soft tissue mass centered in the sphenopalatine foramen, often with anterior bowing of the posterior wall of the maxillary sinus (Holman-Miller sign) and bone remodeling. A biopsy (Option B) in an outpatient setting is absolutely contraindicated because these tumors are extremely vascular, and attempting a biopsy can lead to life-threatening, uncontrollable hemorrhage. The diagnosis is typically made based on the characteristic clinical and radiological findings, with biopsy only performed in a controlled operating room setting after embolization.",
