      "explanation": "The disaster management cycle is typically divided into four phases : Mitigation, Preparedness, Response, and Recovery. The Recovery phase is the period after the immediate impact of the disaster, focused on restoring the community to a normal or improved state. This phase itself has short-term and long-term components. The immediate actions after the disaster, such as search and rescue, providing emergency medical care, food, and shelter, are part of the Response phase. These actions transition into the Rehabilitation and Reconstruction phase, which involves restoring services, rebuilding infrastructure, and providing psychosocial support. Therefore, both Response (immediate actions) and Rehabilitation (longer-term restoration) are key components that constitute the overall recovery process. Mitigation and Preparedness (Options B, C, D) are pre-disaster activities aimed at reducing the impact and preparing to handle a future disaster.",
