      "number": 200,
      "statement": "A pregnant woman delivers a healthy baby through normal vaginal delivery. What is the earliest time at which an intrauterine contraceptive device (IUCD) can be safely inserted?",
      "options": [
        "Within 48 hours",
        "After 6 weeks",
        "After 3 months",
        "After 1 month"
      ],
      "correct": "A",
      "answerText": "(A) Within 48 hours",
      "explanation": "An intrauterine contraceptive device (IUCD) can be inserted at several points after childbirth. The earliest opportunity is post-placental insertion, which is done within 10 minutes of placental delivery. If this window is missed, the next opportunity is immediate postpartum insertion, which can be done within 48 hours of delivery, before the woman is discharged from the hospital. This is a safe and convenient time for many women to receive effective long-term contraception. If insertion is not done within 48 hours, it is generally recommended to wait until the puerperal period is over, typically at the postnatal check-up around 6 weeks postpartum (Option B), to allow the uterus to fully involute and reduce the risk of expulsion or perforation. Therefore, the earliest time frame among the given options is within 48 hours.",
