      "explanation": "The flowchart perfectly illustrates the components of the Human Development Index (HDI). HDI is a composite statistic used by the United Nations Development Programme (UNDP) to rank countries into four tiers of human development. It is based on three key dimensions and their respective indicators : 1. Health, measured by life expectancy at birth; 2. Education, measured by a combination of the mean years of schooling for adults and the expected years of schooling for children; and 3. Standard of Living, measured by Gross National Income (GNI) per capita (adjusted for purchasing power parity). The diagram correctly shows these three dimensions and their underlying indicators converging to form the index. The Physical Quality of Life Index (PQLI) (Option B) used different indicators (infant mortality, life expectancy at age one, and basic literacy). The poverty indices (Options C and D) measure deprivation rather than achievement.",
