      "explanation": "The Physical Quality of Life Index (PQLI) was developed in the 1970s as an alternative to using purely economic indicators like Gross National Product (GNP) to measure a country's development. A key feature of the PQLI is that it deliberately excludes economic indicators. It is a composite index based on three social indicators that reflect the outcomes of development : 1. Life expectancy at the age of one year, 2. The infant mortality rate, and 3. The basic literacy rate. Each indicator is scaled from 0 to 100, and the PQLI is the average of these three scaled scores. Therefore, Gross National Product (GNP) is explicitly not a component of the PQLI, as the index was designed to measure quality of life independent of national income.",
