      "number": 211,
      "statement": "Which vaccine should be stored at the lowest level of an Ice-Lined Refrigerator (ILR)?",
      "options": [
        "OPV",
        "DPT",
        "Hep B",
        "Rota"
      ],
      "correct": "A",
      "answerText": "(A) OPV",
      "explanation": "Ice-Lined Refrigerators (ILRs) are used in the vaccine cold chain to maintain a stable temperature between +2°C and +8°C. However, there is a temperature gradient within the refrigerator, with the bottom being the coldest part, sometimes approaching 0°C. Vaccines are arranged according to their sensitivity to heat and cold. Oral Polio Vaccine (OPV) is the most heat-sensitive vaccine in the routine immunization schedule, but it is also freeze-resistant. Therefore, OPV and other polio vaccines are placed in the bottom basket of the ILR, where it is coldest, to maximize their potency. In contrast, freeze-sensitive vaccines, such as DPT (Diphtheria-Pertussis-Tetanus), Hepatitis B, and Pentavalent vaccines, must be protected from freezing. These are placed in the upper baskets of the ILR to keep them away from the coldest zone at the bottom, as freezing can irreversibly destroy their immunogenicity.",
