      "answerText": "(A) Impact → Response → Rehabilitation → Mitigation",
      "explanation": "Disaster management follows a systematic sequence of phases to minimize the effects of disasters and help communities recover effectively.\n1. Impact : This is the stage when the disaster actually occurs (e.g., earthquake, flood, cyclone). It causes damage to life, property, and infrastructure.\n2. Response : Immediately after the disaster, emergency actions are taken to save lives and reduce suffering. This includes search and rescue operations, first aid, evacuation, providing food, shelter, and medical care.\n3. Rehabilitation : In this phase, efforts focus on restoring normal life. It includes rebuilding homes, restoring infrastructure, providing financial assistance, and supporting affected communities.\n4. Mitigation : Mitigation involves long-term measures to reduce the risk and impact of future disasters. Examples include building stronger infrastructure, disaster preparedness training, early warning systems, and improved planning.\nThus, the correct chronological order is:\nImpact → Response → Rehabilitation → Mitigation, which corresponds to Option (A).",
