      "answerText": "(C) 14 days",
      "explanation": "Quarantine is the restriction of movement of healthy individuals who have been exposed to a communicable disease, for a duration of time to see if they become ill. The purpose is to prevent transmission during the incubation period if they are indeed infected. The quarantine period is determined by the longest known incubation period for the specific disease. This ensures that if the exposed person is going to develop the disease, they will do so while they are separated from the general population. In this case, the incubation period is given as a range of 5-14 days. Therefore, the quarantine period should be set at the maximum possible incubation period, which is 14 days. This provides a sufficient window to cover nearly all individuals who would develop the disease after exposure.",
