      "answerText": "(C) Treponema",
      "explanation": "This constellation of clinical findings is highly characteristic of secondary syphilis, which is caused by the spirochete Treponema pallidum. The asymptomatic, diffuse, macular or maculopapular rash, often involving the palms and soles, is a classic sign. Moth-eaten alopecia is a specific type of non-scarring hair loss on the scalp that can occur in this stage. The moist, hypertrophic, wart-like lesions in the perianal and genital regions are known as condylomata lata, which are highly infectious and pathognomonic for secondary syphilis. These systemic manifestations occur weeks to months after the initial primary chancre and are due to the hematogenous dissemination of the treponemes throughout the body. The other organisms listed do not cause this unique combination of rash, alopecia, and condylomata lata.",
