      "correct": "D",
      "answerText": "(D) IgA deposits at the dermoepidermal junction",
      "explanation": "The patient's combination of an itchy, blistering skin rash and gastrointestinal issues is the classic presentation of Dermatitis Herpetiformis (DH), which is a skin manifestation of Celiac disease.\nThe most definitive and specific finding for DH is revealed by a skin biopsy of the unaffected skin adjacent to a lesion. When examined with direct immunofluorescence, this biopsy shows granular IgA deposits at the dermoepidermal junction. This finding is the gold standard for diagnosis and is the direct cause of the skin inflammation and blistering.\nWhile the patient is also very likely to have positive blood tests for (A) Anti-TTG antibodies and (C) Anti-endomysial antibodies due to the underlying Celiac disease, the IgA skin deposit is the most direct diagnostic marker for the skin lesions themselves. (B) Anti-nuclear antibodies are not associated with this condition.",
