      "correct": "C",
      "answerText": "(C) A : Apocrine gland; B : Eccrine gland; C : Sebaceous gland; D : Arrector pili muscle",
      "explanation": "The diagram shows the histological structure of a hair follicle with associated skin appendages.\nA – Apocrine gland : This is the large coiled gland located deeper in the dermis, usually opening into the hair follicle. Apocrine glands are found in areas such as the axilla, areola, and anogenital region.\nB – Eccrine gland : This appears as a coiled tubular gland located deeper in the dermis, but its duct opens directly onto the skin surface, not into the hair follicle. It is responsible for thermoregulation through sweat secretion.\nC – Sebaceous gland : The lobulated yellow gland attached to the hair follicle represents the sebaceous gland, which secretes sebum to lubricate the hair and skin.\nD – Arrector pili muscle : This is the small smooth muscle attached obliquely to the hair follicle. When it contracts (e.g., in cold or fear), it causes piloerection or “goose bumps.”\nThus, the correct identification of the labeled structures is : A – Apocrine gland, B – Eccrine gland, C – Sebaceous gland, D – Arrector pili muscle.",
