      "answerText": "(B) Pemphigus vulgaris",
      "explanation": "The combination of clinical and immunofluorescence findings is diagnostic of Pemphigus Vulgaris. Clinically, this autoimmune blistering disease is characterized by flaccid bullae and painful erosions on both the skin and mucous membranes (the buccal mucosa involvement is key). The direct immunofluorescence (DIF) image shows the pathognomonic finding : a lace-like or chicken-wire pattern of IgG deposition on the surface of keratinocytes within the epidermis. This indicates the presence of autoantibodies directed against desmoglein-3 (and sometimes desmoglein-1), which are adhesion proteins in the desmosomes that hold keratinocytes together. This attack leads to a loss of cell-to-cell adhesion (acantholysis) and the formation of intra epidermal blisters. Bullous pemphigoid (Option A) is a subepidermal disease with linear IgG at the basement membrane zone. Dermatitis herpetiformis (C) has granular IgA in the dermal papillae.",
