      "answerText": "(B) Tinea capitis",
      "explanation": "The presentation of patchy alopecia (hair loss) associated with scaling and itching in a child is highly suggestive of tinea capitis, a fungal infection of the scalp hair shafts and follicles caused by dermatophytes (e.g., Trichophyton, Microsporum). The fact that a sibling has similar lesions points to an infectious and contagious etiology, which is very common with tinea capitis. Clinical patterns can vary and include black dot (broken hairs), gray patch (scaling with dull hair), or an inflammatory kerion. In contrast, alopecia areata (Option A) is an autoimmune condition that typically causes smooth, non-scaly, completely bald patches. Pediculosis capitis (head lice, Option C) causes intense itching but does not typically cause patchy hair loss and scaling. Pyoderma (Option D) is a bacterial skin infection that would present with pustules or crusting.",
