      "number": 233,
      "statement": "A 45-year-old woman presents to the outpatient department complaining of persistent feelings of tension along with gastrointestinal symptoms such as stomach discomfort, heartburn, and diarrhea. She reports that these complaints have been present for many years. She also mentions that several members of her family tend to feel tense and nervous as well. Based on this clinical history, which of the following additional symptoms is most likely to be observed in this patient?",
