      "answerText": "(B) Tingling of extremities",
      "explanation": "The patient's long-standing history of feeling tense, coupled with prominent somatic symptoms (stomach upset, heartburn, diarrhea), is highly suggestive of an anxiety disorder, most likely Generalized Anxiety Disorder (GAD). GAD is characterized by excessive, uncontrollable worry about multiple aspects of life, accompanied by physical symptoms of autonomic arousal and muscle tension. These physical symptoms can include restlessness, fatigue, muscle aches, and gastrointestinal distress. Tingling of the extremities (paresthesias) is a very common somatic symptom of anxiety, often related to hyperventilation which can occur during periods of high anxiety. The other options are symptoms of psychosis and are not characteristic of anxiety disorders. Ideas of reference (A), hallucinations (C), and neologisms (D) are seen in conditions like schizophrenia.",
