      "answerText": "(A) Subarachnoid hemorrhage (SAH) - aneurysm",
      "explanation": "The non-contrast CT scan shows hyperdense material (which represents acute blood) filling the subarachnoid spaces. Specifically, blood can be seen in the basal cisterns, the Sylvian fissures, and the interhemispheric fissure, outlining the sulci and gyri. This pattern is pathognomonic for a subarachnoid hemorrhage (SAH). The most common cause of a non-traumatic SAH (in about 85% of cases) is the rupture of a saccular or berry aneurysm, typically located at the branch points of the arteries of the circle of Willis. The patient's complaint of headache is the classic symptom (worst headache of my life). An epidural hemorrhage (Option B) is typically lens-shaped (biconvex), while a subdural hemorrhage (Option C) is crescent-shaped. An intraparenchymal hemorrhage (Option D) would be located within the brain tissue itself.",
