      "number": 246,
      "statement": "Based on the radiograph showing a foreign body lodged in the esophagus, which characteristic radiological sign is associated with this finding?",
      "options": [
        "String sign",
        "Double ring sign",
        "Steeple sign",
        "Thumb sign"
      ],
      "correct": "B",
      "answerText": "(B) Double ring sign",
      "explanation": "The radiograph shows a coin lodged in the esophagus. When a button battery is ingested and lodged in the esophagus, it presents a significant medical emergency due to the risk of liquefaction necrosis and perforation. On an anteroposterior (AP) X-ray, a button battery has a characteristic appearance that distinguishes it from a simple coin : the double-ring or halo sign. This is because the battery has two components a smaller inner circle and a larger outer casing creating a two-layered appearance. While the image provided may be a simple coin, this sign is the one most famously associated with a dangerous esophageal foreign body of this shape. The steeple sign (C) and thumb sign (D) are seen in croup and epiglottitis, respectively. The string sign (A) is seen in barium studies of Crohn's disease.",
