      "number": 247,
      "statement": "An 18-year-old boy presents with fever, localized tenderness, and warmth over a bone. Laboratory investigations reveal raised inflammatory markers, including an elevated ESR and CRP. A radiograph of the affected area is shown below. Based on the clinical presentation, laboratory findings, and radiographic appearance, what is the most likely diagnosis?",
