      "answerText": "(B) Glomus tympanicum",
      "explanation": "The clinical symptoms of pulsatile tinnitus (hearing a heartbeat in the ear) and conductive hearing loss are highly suggestive of a vascular tumor in the middle ear. The provided axial CT scan of the temporal bone confirms this by showing a well-defined, soft-tissue mass located on the cochlear promontory within the middle ear cavity. This is the classic location and appearance of a glomus tympanicum, which is a paraganglioma arising from glomus bodies on the promontory. On otoscopy, it appears as a reddish-blue mass behind an intact tympanic membrane. A glomus jugulare (Option A) is a larger tumor arising from the jugular bulb, which would typically show erosion of the floor of the middle ear, a feature not specified here. An acoustic neuroma (Option C) is a tumor in the internal auditory canal causing sensorineural hearing loss. Otosclerosis (Option D) is a disease of the bone and would not appear as a soft tissue mass.",
