      "correct": "B",
      "answerText": "(B) Barium Swallow",
      "explanation": "The image depicts a dynamic imaging procedure where a contrast agent is used to visualize the pharynx and esophagus in real-time. The patient swallows a liquid suspension containing barium sulfate, and its passage is observed using fluoroscopy (a continuous X-ray beam). This specific procedure is known as a barium swallow or esophagogram. It is used to evaluate the anatomy and function (motility) of the esophagus and to detect structural abnormalities such as strictures, diverticula, hiatal hernias, tumors, or motility disorders like achalasia. While fluoroscopy (Option A) is the imaging modality being used, Barium Swallow is the specific name of the diagnostic investigation shown. Ingesting acid or alkali (Options C and D) are causes of esophageal injury, not diagnostic procedures; a contrast study might be performed later to assess the damage from such an ingestion.",
