      "correct": "A",
      "answerText": "(A) Choledochal cyst",
      "explanation": "The MRCP image displays a significant, well-defined, fusiform or saccular dilation of the common bile duct, which is the characteristic feature of a choledochal cyst. Choledochal cysts are congenital malformations of the biliary tree involving cystic dilation of the bile ducts. The Todani classification system is used to categorize different types, with Type I (fusiform dilation of the common bile duct, as likely shown) being the most common. While the common bile duct is indeed dilated (Option C), choledochal cyst is the specific pathological diagnosis for this congenital condition, not just a description of the finding. Cholangiocarcinoma (Option B) would typically appear as an irregular stricture or an intraductal mass rather than a smooth, cystic dilation. Acute cholecystitis (Option D) involves inflammation of the gallbladder, which is not the primary finding shown here.",
