      "explanation": "The most accurate and defining statement about the EMLA patch is that it utilizes a eutectic mixture. In fact, the name EMLA is an acronym for Eutectic Mixture of Local Anesthetics.\nA eutectic mixture is a specific blend of substances that melt at a lower temperature than either of the individual components. In the case of EMLA :\nIts active ingredients, lidocaine and prilocaine, are both solid crystalline powders at room temperature.\nWhen they are mixed in a 1 :1 ratio, they form an oil (a liquid at room temperature).\nThis innovative formulation allows for a very high concentration of the local anesthetics to be prepared in a cream or patch, which enables effective penetration through intact skin to numb the area.\nAnalysis of Other Options\n1. (A) Adverse effect is methemoglobinemia : This is also a true statement. Prilocaine, one of the active ingredients, can cause methemoglobinemia (a condition where blood cannot carry oxygen effectively) as a rare but serious side effect, especially in infants. However, option (C) describes the fundamental principle of the product's formulation.\n2. (B) Contains bupivacaine & lignocaine : This is incorrect. EMLA contains prilocaine and lignocaine (lidocaine), not bupivacaine.\n3. (D) 0.5% concentration of lignocaine has 50 mg in 1 gm is used : This is incorrect. A 0.5% concentration means 0.5 g per 100 g, which equals 5 mg per 1 g, not 50 mg. Furthermore, the actual concentration of each anesthetic in EMLA is 2.5% (25 mg/g).",
