      "answerText": "(A) Constrictive pericarditis",
      "explanation": "The combination of findings is classic for constrictive pericarditis. In this condition, a thickened, fibrotic, and often calcified pericardium encases the heart, restricting its diastolic filling. This leads to signs of right heart failure (elevated JVP, edema, ascites). The JVP waveform is characteristic : it shows a prominent and rapid 'y' descent (Friedreich's sign), which reflects the rapid early diastolic filling of the ventricle before it is abruptly halted by the constricting pericardium. This abrupt halt in filling also produces a high-pitched diastolic sound called a pericardial knock. Atrial fibrillation (causing the irregularly irregular pulse) is also common due to chronically elevated atrial pressures. In cardiac tamponade (Option B), the 'y' descent is blunted or absent. Mitral stenosis (Option C) causes an opening snap, not a pericardial knock.",
