      "correct": "B",
      "answerText": "(B) BP control and monitoring",
      "explanation": "The patient's presentation is a textbook case of acute aortic dissection. The combination of a history of hypertension, excruciating chest pain—often described as a sudden tearing sensation radiating to the back—and unequal radial pulses is highly specific for this diagnosis. The pulse difference occurs when the dissection flap obstructs blood flow into major arteries supplying the arms, like the brachiocephalic or subclavian arteries.\nThis is a life-threatening emergency where the immediate goal is to reduce the hemodynamic forces tearing the aorta apart. This is achieved with aggressive BP control and monitoring, often called anti-impulse therapy. The aim is to rapidly lower both the systolic blood pressure (target 100-120 mmHg) and the heart rate (target ~60 bpm) to decrease shear stress on the aortic wall. Intravenous beta-blockers like labetalol are the cornerstone of this initial management for all patients.\nWhile (A) emergency surgery is the definitive treatment for dissections involving the ascending aorta (Type A), it can only proceed after the patient is medically stabilized with blood pressure control. Uncomplicated dissections of the descending aorta (Type B) are often managed with BP control alone, while (C) stenting is reserved for complicated cases.",
