      "number": 277,
      "statement": "A patient presents with acute shortness of breath, tachycardia (HR 120/min), and hypotension (BP 90/60 mm Hg). Echocardiography reveals diastolic collapse of the ventricles. What is the most appropriate management for this patient?",
