      "correct": "C",
      "answerText": "(C) Increased oxygen consumption in the heart",
      "explanation": "Angina pectoris in the setting of severe aortic stenosis (AS) is due to a mismatch between myocardial oxygen supply and demand. In AS, the left ventricle (LV) has to generate extremely high pressures to pump blood across the stenotic aortic valve. This chronic pressure overload leads to significant concentric left ventricular hypertrophy (LVH). A hypertrophied myocardium has a massively increased oxygen demand (consumption) due to the increased muscle mass and wall stress. At the same time, myocardial oxygen supply can be compromised. The high intraventricular pressures during systole compress the subendocardial coronary arteries, reducing coronary blood flow, especially during exercise when diastolic filling time is shortened. This combination of dramatically increased oxygen demand and potentially reduced supply results in subendocardial ischemia, which manifests as angina, even in the absence of coronary artery disease.",
