      "number": 282,
      "statement": "A 15-year-old patient presents with joint swelling, a pansystolic murmur, raised ESR, and a negative rheumatoid factor. There is a recent history of sore throat, along with subcutaneous nodules and erythema marginatum on examination. What is the most likely diagnosis?",
