      "correct": "B",
      "answerText": "(B) Leptospirosis",
      "explanation": "This constellation of symptoms is highly characteristic of leptospirosis. A farmer is at occupational risk of this zoonotic disease, caused by the spirochete Leptospira, which is transmitted through contact with water or soil contaminated by infected animal urine. The classic presentation of the initial septicemic phase includes an abrupt onset of high fever, chills, headache (often retro-orbital), and severe myalgia. The myalgia is particularly prominent in the calves, causing severe pain and tenderness. The most specific sign described is bilateral conjunctival suffusion, which is redness of the conjunctiva without an inflammatory exudate, and it is a pathognomonic feature of leptospirosis. While dengue (A) can cause fever and retro-orbital pain, the severe calf pain and conjunctival suffusion make leptospirosis a much more likely diagnosis.",
