      "number": 286,
      "statement": "An athlete collapses and dies suddenly while playing school basketball. On histological examination of the heart, which finding or condition is most likely to be present?",
      "options": [
        "Dilated cardiomyopathy (DCM)",
        "Restrictive cardiomyopathy (RCM)",
        "Arrhythmogenic right ventricular dysplasia (ARVD)",
        "Hypertrophic cardiomyopathy (HCM)"
      ],
