      "answerText": "(D) Hypertrophic cardiomyopathy (HCM)",
      "explanation": "Sudden cardiac death in a young, apparently healthy athlete is a tragic event, and the most common underlying cause is Hypertrophic Cardiomyopathy (HCM). HCM is a genetic disorder characterized by unexplained thickening (hypertrophy) of the left ventricular myocardium. The histology of HCM is pathognomonic, showing cardiomyocyte hypertrophy, extensive myofiber disarray (a chaotic arrangement of muscle cells), and interstitial fibrosis. This disorganized myocardial architecture creates an electrical instability that makes the heart vulnerable to lethal ventricular arrhythmias (like ventricular fibrillation), especially during the intense sympathetic stimulation of exercise. This arrhythmia is the terminal event that causes the sudden collapse and death. ARVD (C) is another cause but is less common and involves fibrofatty replacement of the right ventricle. DCM (A) and RCM (B) are less common causes of sudden death in this specific population.",
