      "explanation": "The chest X-ray shows dextrocardia (the heart is on the right side of the chest), which is a component of situs inversus. The patient's history of recurrent lung infections suggests an underlying problem with airway clearance, such as bronchiectasis. The combination of situs inversus, chronic sinusitis, and bronchiectasis forms the classic triad of Kartagener syndrome. This is a subtype of primary ciliary dyskinesia (PCD), an autosomal recessive genetic disorder. The underlying defect is in the dynein arms of cilia, rendering them immotile or dysfunctional. This impairs mucociliary clearance in the respiratory tract, leading to recurrent infections and bronchiectasis. It also affects sperm motility (causing infertility in males) and the cilia responsible for organ rotation during embryogenesis, leading to situs inversus in about 50% of PCD patients. Cystic fibrosis (B) causes bronchiectasis but not situs inversus.",
