      "answerText": "(C) Type 3 von Willebrand disease is associated with a complete absence of factor VIII.",
      "explanation": "von Willebrand disease is the most common inherited bleeding disorder and results from deficiency or dysfunction of von Willebrand factor (vWF). vWF plays an important role in platelet adhesion and also helps stabilize factor VIII in circulation.\nType 1 von Willebrand disease is the most common and mildest form, caused by a partial quantitative deficiency of vWF. Patients usually present with mild mucocutaneous bleeding, such as epistaxis, menorrhagia, or easy bruising, rather than severe bleeding since childhood.\nType 2 von Willebrand disease is a qualitative defect in vWF and includes several subtypes (2A, 2B, 2M, 2N) with different functional abnormalities. These patients typically have a moderate bleeding tendency.\nType 3 von Willebrand disease is the most severe form, characterized by a near-complete absence of vWF. Because vWF stabilizes factor VIII, its levels are markedly reduced, but factor VIII is not completely absent.\nTherefore, statement (C) is incorrect because factor VIII is reduced but not completely absent in Type 3 von Willebrand disease.",
