    {
      "number": 304,
      "statement": "A patient presents with enlarged, sweaty hands, macroglossia, and frontal bossing. What is the most appropriate test to confirm the diagnosis?",
      "options": [
        "GHRH levels",
        "IGF-1",
        "IGF-2",
        "GH levels after glucose suppression"
      ],
      "correct": "B",
      "answerText": "(B) IGF-1",
      "explanation": "The clinical features described—enlarged sweaty hands, macroglossia, and frontal bossing—are characteristic of Acromegaly, a disorder caused by excess secretion of growth hormone (GH), usually from a pituitary adenoma. Excess GH leads to increased production of insulin-like growth factor-1 (IGF-1) in the liver, which mediates most of the tissue growth and metabolic effects seen in acromegaly.\nFor diagnosis, the most appropriate initial screening test is measurement of IGF-1 levels. IGF-1 is preferred because its concentration remains relatively stable throughout the day, reflecting the average GH secretion. In contrast, growth hormone levels fluctuate widely due to pulsatile secretion, making random GH measurements unreliable.\nIf IGF-1 levels are elevated, the diagnosis is usually confirmed by a glucose suppression test, in which GH levels are measured after oral glucose administration. In normal individuals, glucose suppresses GH secretion, but in acromegaly GH levels fail to suppress.\nThus, serum IGF-1 measurement is the best test to confirm suspected acromegaly initially.",
      "pages": [
        125,
        213
      ]
    }
