      "answerText": "(B) Esophageal varices",
      "explanation": "Esophageal varices are enlarged, tortuous veins in the lower esophagus that develop due to portal hypertension, most commonly associated with Liver cirrhosis. Increased pressure in the portal venous system causes blood to divert through collateral vessels, including veins in the esophagus.\nDuring endoscopic examination, esophageal varices appear as bulging, dilated, bluish or reddish longitudinal veins projecting into the esophageal lumen, as seen in the image. These veins are fragile and can rupture easily, leading to massive upper gastrointestinal bleeding, which is a life-threatening complication.\nOther options are less consistent with the endoscopic appearance. Barrett’s esophagus shows salmon-colored columnar epithelium replacing the normal squamous lining. Gastric erosion involves superficial mucosal damage in the stomach rather than the esophagus. Chronic GERD typically shows esophagitis with mucosal inflammation or ulceration, not dilated veins.\nTherefore, the endoscopic image showing prominent dilated veins in the esophagus is most consistent with esophageal varices.",
