      "correct": "C",
      "answerText": "(C) Ureteroscope",
      "explanation": "The instrument shown is a flexible ureteroscope. This is a type of endoscope specifically designed for visualizing and performing procedures within the urinary tract. Key features that identify it as a flexible ureteroscope are its long, thin, and flexible shaft, which allows it to be passed transurethrally, through the bladder, and up into the ureter and renal pelvis. The handle contains controls for deflecting the tip in different directions (active deflection), an eyepiece or a connection for a video camera, and working channels for the passage of irrigation fluid, laser fibers, stone baskets, or biopsy forceps. A cystoscope (Option B) is used to look inside the bladder and can be rigid or flexible but is shorter. A nephroscope (Option A) is a rigid or flexible scope used for percutaneous access to the kidney. A laparoscope (D) is a rigid scope for abdominal surgery.",
