      "answerText": "(A) Diphtheria antitoxin",
      "explanation": "The presence of a pseudomembrane on the pharynx or tonsils in an unimmunized child is highly suspicious for respiratory diphtheria. This is a medical emergency because the disease is caused by a potent exotoxin produced by Corynebacterium diphtheriae. This toxin can cause severe local airway obstruction and systemic effects, including myocarditis and neuropathy. The single most important and life-saving step in management is the prompt administration of diphtheria antitoxin (DAT). The antitoxin is a passive immunization that contains pre-formed antibodies to neutralize any circulating toxin that has not yet bound to host cells. It must be given immediately on the basis of clinical suspicion, without waiting for laboratory confirmation, as its efficacy decreases significantly once the toxin is cell-bound. Antibiotics like penicillin (C) are also given to eradicate the bacteria but are secondary to antitoxin administration.",
