      "answerText": "(C) Lymphoid Growth",
      "explanation": "The graph represents the Scammon’s growth curves, which describe the growth patterns of different body tissues from birth to adulthood. These curves include neural (brain), lymphoid, somatic, and genital growth.\nLabel A shows a curve that rises rapidly during childhood, reaches a peak of about 200% of adult size around 10–12 years, and then declines to the adult level by around 20 years. This characteristic pattern corresponds to lymphoid tissue growth.\nScammon's growth curves show that lymphoid tissues such as the tonsils, adenoids, thymus, and lymph nodes grow very rapidly during childhood due to increased immune activity. During adolescence, these tissues undergo involution, resulting in a reduction in size toward adult levels.\nFor comparison:\n1. Brain (neural) growth rises rapidly early and reaches about 90% of adult size by 5–6 years.\n2. Somatic growth follows a steady pattern with an adolescent growth spurt.\n3. Gonadal growth remains minimal until puberty and then increases sharply.\nTherefore, label A represents lymphoid growth.",
