      "number": 346,
      "statement": "Where is the flexion point located in ventouse (vacuum-assisted) delivery?",
      "options": [
        "3 cm posterior to the anterior fontanelle",
        "3 cm anterior to the posterior fontanelle",
        "6 cm anterior to the posterior fontanelle",
        "Midway between the anterior and posterior fontanelle"
      ],
      "correct": "B",
      "answerText": "(B) 3 cm anterior to the posterior fontanelle",
      "explanation": "Proper placement of the vacuum cup (ventouse) is critical for a successful and safe vacuum-assisted delivery. The cup should be placed over the flexion point on the fetal scalp. This point is located on the sagittal suture, approximately 3 cm anterior to the posterior fontanelle and about 6 cm posterior to the anterior fontanelle. Placing the cup at this specific point ensures that when traction is applied, the force promotes flexion of the fetal head. This flexion presents the smallest possible diameter of the head (the suboccipitobregmatic diameter) to the maternal pelvis, which facilitates descent and delivery and minimizes trauma to both mother and baby. Placing the cup too far anteriorly would cause head extension, while placing it too far posteriorly could cause deflexion, both of which are undesirable.",
