      "explanation": "The instrument shown is a pair of Piper's forceps. These obstetric forceps are uniquely designed for the delivery of the after coming head in a breech presentation. Their most distinctive features are their long shanks which have a significant perineal curve (a backward and upward curve). This specific design allows the forceps to be applied to the fetal head while it is still high in the maternal pelvis, without the blades compressing or interfering with the already-delivered fetal body. The long, curved shanks accommodate the perineum and the baby's trunk. Kielland's forceps (A) are used for rotational deliveries. Wrigley's forceps (B) are outlet forceps with short shanks. Simpson's forceps (D) are classic forceps for routine outlet or low-forceps deliveries. The perineal curve is the key identifying feature of Piper's forceps.",
