      "explanation": "Burns–Marshall maneuver. Burns–Marshall maneuver is an obstetric technique used during breech delivery to assist the delivery of the after coming head of the fetus. In this maneuver, once the body of the baby has been delivered, the fetus is allowed to hang downward until the nape of the neck becomes visible under the symphysis pubis. The obstetrician then lifts the fetal body upward in an arc over the mother’s abdomen, which helps the head flex and deliver smoothly. The sequence of images shows:\n1. Delivery of the breech and body of the fetus.\n2. The fetus hanging downward to promote head flexion.\n3. The obstetrician holding the fetal ankles/ body.\n4. Upward sweeping movement to deliver the after coming head. Other options differ:\n1. Lovset maneuver – used to deliver extended arms in breech presentation.\n2. Mauriceau–Smellie–Veit maneuver – involves supporting the fetal head with fingers in the mouth to maintain flexion. Thus, the maneuver depicted corresponds to the Burns–Marshall maneuver.",
