      "correct": "B",
      "answerText": "(B) Carboprost",
      "explanation": "Management of postpartum hemorrhage (PPH) involves uterotonic drugs to make the uterus contract. While several agents are available, their use must be tailored to the patient's comorbidities. Carboprost tromethamine (Hemabate) is a synthetic prostaglandin analogue (PGF2α) that is a potent uterotonic. However, prostaglandins can also cause bronchoconstriction. Because of this risk, carboprost is relatively or absolutely contraindicated in patients with asthma, as it can precipitate a severe asthma attack. Oxytocin (D) is the first-line agent and is safe. Methylergometrine (A) is effective but is contraindicated in patients with hypertension or pre-eclampsia.",
