      "explanation": "In fertility-preserving surgery for uterine prolapse, procedures such as Sacrospinous hysteropexy are commonly performed. In this technique, the uterus is suspended to the sacrospinous ligament, which is located near the ischial spine.\nThe Ischial spine serves as an important surgical landmark because the sacrospinous ligament attaches to it. During surgery, sutures are placed in the sacrospinous ligament close to the ischial spine to support and elevate the prolapsed uterus while preserving fertility.\nOther options are less appropriate:\n1. Sacral promontory – used in sacrocolpopexy, typically after hysterectomy.\n2. Pubic symphysis – not used for prolapse suspension procedures.\n3. Ischial tuberosity – mainly associated with muscle attachments, not prolapse repair.\nThus, in fertility-preserving uterine suspension procedures, the ischial spine is the key bony landmark used.",
