      "correct": "B",
      "answerText": "(B) 46 XX",
      "explanation": "A teenage girl presenting with primary amenorrhea and the genital finding shown in the image is most consistent with an Imperforate hymen. In this condition, menstrual blood cannot exit the vagina, leading to hematocolpos or hematometra, which may present as primary amenorrhea with cyclic abdominal pain.\nImportantly, imperforate hymen is an outflow tract obstruction, not a chromosomal abnormality. The ovaries, uterus, and hormonal function are usually normal, and secondary sexual characteristics develop normally.\nTherefore, the patient typically has a normal female karyotype, which is 46 XX.\nOther options are associated with different conditions:\n1. 46 XY – seen in androgen insensitivity syndrome or gonadal dysgenesis.\n2. 45 XO – seen in Turner syndrome, associated with streak ovaries and delayed puberty.\n3. 47 XXY – seen in Klinefelter syndrome.\nThus, the most appropriate karyotype is 46 XX.",
