      "number": 366,
      "statement": "A woman presents with bleeding after sexual intercourse. What is the most appropriate investigation to evaluate this symptom?",
      "options": [
        "Pap smear, HCV DNA, electrophoresis",
        "Liquid-based cytology, cervical biopsy",
        "Cervical biopsy, HBV DNA",
        "Pap smear, HPV DNA testing"
      ],
      "correct": "D",
      "answerText": "(D) Pap smear, HPV DNA testing",
      "explanation": "Postcoital bleeding (bleeding after intercourse) is a potential symptom of cervical pathology, including cervical cancer, and it always warrants a thorough investigation. The initial workup should include a speculum examination to visualize the cervix and screening for cervical cancer. Current screening guidelines emphasize co-testing, which combines a Pap smear (or its modern equivalent, Liquid-Based Cytology) with HPV DNA testing. The Pap smear looks for abnormal cells (dysplasia) on the cervix, while the HPV test detects the presence of high-risk strains of the Human Papillomavirus, which is the causative agent of nearly all cervical cancers. If the speculum exam reveals a visible lesion, a direct cervical biopsy (Option B) would be performed immediately. However, in the absence of a gross lesion, co-testing is the standard initial investigatory step.",
      "pages": [
        135,
        228
      ]
