    {
      "number": 367,
      "statement": "A 32-year-old woman presents with a newly developed 2 cm black nodular lesion near her episiotomy scar. The lesion is painful and enlarges during menstruation. What is the most likely diagnosis?",
      "options": [
        "Endometriosis",
        "Melanoma",
        "Foreign body granuloma",
        "Inclusion cyst"
      ],
      "correct": "A",
      "answerText": "(A) Endometriosis",
      "explanation": "The key feature in this clinical history is the cyclical nature of the symptoms—the mass becomes painful and larger during menstruation. This strongly suggests that the tissue is hormonally responsive, specifically to estrogen and progesterone. This is the hallmark of endometriosis, which is the presence of ectopic endometrial tissue. Scar endometriosis can occur when endometrial cells are inadvertently seeded into a surgical incision, such as an episiotomy scar or a C-section scar, during delivery. This ectopic tissue then responds to hormonal cycles, proliferating and bleeding monthly, which causes the cyclical pain and swelling. The black or bluish appearance is due to trapped, hemolyzed blood. While melanoma (B) can be a black nodule, it would not have cyclical changes. A foreign body granuloma (C) or inclusion cyst (D) would also not be expected to fluctuate with the menstrual cycle.",
      "pages": [
        135,
        228
      ]
    }
