      "correct": "A",
      "answerText": "(A) Dynamic hip screw",
      "explanation": "The implant shown is a Dynamic Hip Screw (DHS), also known as a sliding hip screw. This is a common orthopedic implant used for the internal fixation of certain types of hip fractures, particularly intertrochanteric and stable femoral neck fractures. It consists of two main components : a large-diameter lag screw that is inserted into the femoral head, and a side plate that is fixed to the lateral aspect of the femoral shaft with smaller cortical screws. The key feature is that the lag screw can slide within the barrel of the side plate. This dynamic property allows for controlled collapse or impaction at the fracture site, promoting bone healing under compression while providing stable fixation. Cannulated screws (B) are hollow, and an intramedullary nail (D) is inserted down the shaft of the bone.",
