      "statement": "The patient is unable to form the O sign by opposing the thumb and index finger. Injury to which muscle is most likely responsible for this deficit?",
      "options": [
        "Opponens pollicis",
        "Flexor pollicis brevis",
        "Abductor pollicis brevis",
        "Flexor digitorum"
      ],
